"""Intent tests for risk.max_drawdown: TC-08, the deepest fall with its peak and trough dates (RISK-05)."""

from __future__ import annotations

import pytest

from risk import Drawdown, Returns, max_drawdown


def _returns(data: dict) -> Returns:
    return Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def _tc08(golden) -> tuple[dict[str, Drawdown], dict[str, dict], float]:
    data, expected = golden("risk", "TC-08")
    result = max_drawdown(_returns(data["returns"]))
    by_ticker = {d.ticker: d for d in result}
    assert len(by_ticker) == len(result)
    wanted = {row["ticker"]: row for row in expected["drawdowns"]}
    return by_ticker, wanted, expected["tol"]


@pytest.mark.intent
def test_tc08_one_drawdown_per_ticker(golden):
    by_ticker, wanted, _ = _tc08(golden)
    assert set(by_ticker) == set(wanted)
    for drawdown in by_ticker.values():
        assert isinstance(drawdown, Drawdown)


@pytest.mark.intent
@pytest.mark.parametrize("ticker", ["X", "Y", "Z"])
def test_tc08_depth_matches_within_tolerance(golden, ticker):
    by_ticker, wanted, tol = _tc08(golden)
    assert by_ticker[ticker].depth == pytest.approx(wanted[ticker]["depth"], abs=tol)
    assert by_ticker[ticker].depth <= 0


@pytest.mark.intent
@pytest.mark.parametrize("ticker", ["X", "Y", "Z"])
def test_tc08_peak_and_trough_dates_exact(golden, ticker):
    by_ticker, wanted, _ = _tc08(golden)
    got = by_ticker[ticker]
    assert (got.peak_date, got.trough_date) == (
        wanted[ticker]["peak_date"],
        wanted[ticker]["trough_date"],
    )
    assert got.peak_date <= got.trough_date


@pytest.mark.intent
def test_tc08_no_fall_dates_are_the_first_date(golden):
    data, _ = golden("risk", "TC-08")
    by_ticker, _, _ = _tc08(golden)
    rising = by_ticker["Y"]
    assert rising.depth == 0
    assert rising.peak_date == data["returns"]["base_date"]
    assert rising.trough_date == data["returns"]["base_date"]


@pytest.mark.intent
def test_tc08_first_day_fall_peaks_at_the_base_date(golden):
    data, _ = golden("risk", "TC-08")
    by_ticker, _, _ = _tc08(golden)
    assert by_ticker["Z"].peak_date == data["returns"]["base_date"]

